func TestDatabaseDraftHTTPUsesEphemeralCredentialsWithoutDisclosure(t *testing.T) {
	dsn := strings.TrimSpace(os.Getenv("POSTGRES_DSN"))
	if dsn == "" {
		t.Skip("POSTGRES_DSN is not set")
	}
	parsed, err := url.Parse(dsn)
	if err != nil {
		t.Fatal(err)
	}
	password, _ := parsed.User.Password()
	port, err := strconv.Atoi(parsed.Port())
	if err != nil {
		t.Fatal(err)
	}
	pool, err := store.OpenPool(context.Background(), dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer pool.Close()
	legacy, err := legacycrypt.New(make([]byte, 32))
	if err != nil {
		t.Fatal(err)
	}
	manager := dbexec.New(pool)
	defer manager.Close()
	coordinator, err := integrations.New(pool, store.New(pool, nil), legacy, manager, mcpclient.New("test", slog.Default(), nil), slog.Default())
	if err != nil {
		t.Fatal(err)
	}
	principal := store.Session{User: store.User{ID: 42, Role: "USER", Active: true, Permissions: []string{"database.self.manage"}}, AuthType: "session"}
	api := &API{integrations: coordinator, principal: func(*http.Request) (store.Session, bool) { return principal, true }, logger: slog.Default()}
	payload := map[string]any{
		"name": "ephemeral integration", "databaseName": strings.TrimPrefix(parsed.Path, "/"), "dbms": "POSTGRES",
		"host": parsed.Hostname(), "port": port, "username": parsed.User.Username(), "password": password,
		"options": map[string]string{"sslmode": parsed.Query().Get("sslmode")}, "allowedSchemas": []string{"public"},
		"statementTimeoutSeconds": 30, "maxRows": 1000, "enabled": true,
	}
	body, err := json.Marshal(payload)
	if err != nil {
		t.Fatal(err)
	}
	request := httptest.NewRequest(http.MethodPost, "/databases/owned/test", bytes.NewReader(body))
	response := httptest.NewRecorder()
	api.testOwnDatabaseDraft(response, request)
	if response.Code != http.StatusOK || !strings.Contains(response.Body.String(), `"connected":true`) {
		t.Fatalf("draft connection status=%d body=%s", response.Code, response.Body.String())
	}
	for _, secret := range []string{parsed.Hostname(), parsed.User.Username(), password} {
		if secret != "" && strings.Contains(response.Body.String(), secret) {
			t.Fatalf("draft response disclosed credential-adjacent value %q: %s", secret, response.Body.String())
		}
	}

	payload["options"] = map[string]string{"sslrootcert": "/dev/zero"}
	body, _ = json.Marshal(payload)
	response = httptest.NewRecorder()
	api.testOwnDatabaseDraft(response, httptest.NewRequest(http.MethodPost, "/databases/owned/test", bytes.NewReader(body)))
	if response.Code != http.StatusBadRequest {
		t.Fatalf("client TLS path was not rejected: status=%d body=%s", response.Code, response.Body.String())
	}

	principal.AuthType = "api_key"
	payload["options"] = map[string]string{"sslmode": parsed.Query().Get("sslmode")}
	body, _ = json.Marshal(payload)
	response = httptest.NewRecorder()
	api.testOwnDatabaseDraft(response, httptest.NewRequest(http.MethodPost, "/databases/owned/test", bytes.NewReader(body)))
	if response.Code != http.StatusForbidden || !strings.Contains(response.Body.String(), "interactive_session_required") {
		t.Fatalf("API key draft probe was not denied: status=%d body=%s", response.Code, response.Body.String())
	}
}
